import re
import tkinter as tk
from ..widgets.rmods_frame import RModsFrame
from ..widgets.bbmods_frame import BBModsFrame
from ..widgets.smods_frame import SModsFrame
from ..widgets.cells_frame import CellsFrame
from ..utils.logger import logger


class ViewAcg(tk.Frame):

    def __init__(self, parent, model, *args, **kwargs):
        super().__init__(parent, *args, **kwargs)
        self.model = model

        self.rmods_frame = RModsFrame(self, model)
        self.bbmods_frame = BBModsFrame(self, model)
        self.smods_frame = SModsFrame(self, model)
        self.cells_frame = CellsFrame(self, model)
        self.bbmods_frame.grid(row=0, column=4)
        self.smods_frame.grid(row=1, column=4)
        self.rmods_frame.grid(row=0, column=5, rowspan=2)
        self.cells_frame.grid(column=6, row=0, rowspan=2)

        self.bbmod_name_to_be_deleted = None
        self.available_bbmods_list_prior_bbmod_deletion = None
        self.rmod_id_to_be_deleted = None
        self.fetch_bbmods_func = self.fetch_bbmods
        self.bind_events()

    def bind_events(self):
        self.cb_func = self.bind_all('<<ComboboxSelected>>', lambda ev: self.update_configuration(ev))

        # self.post_add_bbmod_func = self.bind_all('<<PostAddBbmod>>', lambda ev: self.update_view_config(ev))
        # self.post_add_rmod_func = self.bind_all('<<PostAddRmod>>', lambda ev: self.update_view_config(ev))
        # self.post_add_cell_func = self.bind_all('<<PostAddCell>>', lambda ev: self.update_view_config(ev))

        self.post_add_connection_func = self.bind_all('<<PostAddConnectionFrame>>',
                                                      lambda ev: self.post_cell_update(ev))
        self.post_reset_delete_cell_func = self.bind_all('<<PostResetDeleteCell>>',
                                                         lambda ev: self.post_cell_update(ev))
        self.post_reset_delete_cell_func = self.bind_all('<<PostResetDeleteConnection>>',
                                                         lambda ev: self.post_cell_update(ev))

        self.prior_delete_bbmod_func = self.bind_all('<<PriorDeleteBbmod>>', lambda ev: self.prior_delete_bbmod(ev))
        self.post_delete_bbmod_func = self.bind_all('<<PostDeleteBbmod>>', lambda ev: self.post_delete_bbmod(ev))

        self.prior_delete_rmod_func = self.bind_all('<<PriorDeleteRmod>>', lambda ev: self.prior_delete_rmod(ev))
        self.post_delete_rmod_func = self.bind_all('<<PostDeleteRmod>>', lambda ev: self.post_delete_rmod(ev))

        self.prior_reset_rmod_func = self.bind_all('<<PriorResetRmod>>', lambda ev: self.prior_reset_rmod(ev))
        self.post_reset_rmod_func = self.bind_all('<<PostResetRmod>>', lambda ev: self.post_reset_rmod(ev))

    def unbind_events(self):
        self.unbind('<<ComboboxSelected>>', self.cb_func)

        # self.unbind('<<PostAddBbmod>>', self.post_add_bbmod_func)
        # self.unbind('<<PostAddRmod>>', self.post_add_rmod_func)
        # self.unbind('<<PostAddCell>>', self.post_add_cell_func)

        self.unbind('<<PostAddConnectionFrame>>', self.post_add_connection_func)
        self.unbind('<<PostResetDeleteCell>>', self.post_reset_delete_cell_func)
        self.unbind('<<PostResetDeleteConnection>>', self.post_reset_delete_cell_func)

        self.unbind('<<PriorDeleteBbmod>>', self.prior_delete_bbmod_func)
        self.unbind('<<PostDeleteBbmod>>', self.post_delete_bbmod_func)

        self.unbind('<<PriorDeleteRmod>>', self.prior_delete_rmod_func)
        self.unbind('<<PostDeleteRmod>>', self.post_delete_rmod_func)

        self.unbind('<<PriorResetRmod>>', self.prior_reset_rmod_func)
        self.unbind('<<PostResetRmod>>', self.post_reset_rmod_func)

    def update_view_config(self, event=None, profile=None, enb_id=None):

        available_bbmods_list = self.fetch_bbmods_func()
        self.rmods_frame.selected_topology = profile
        self.rmods_frame.enb_id = enb_id
        self.rmods_frame.update_available_bbmods_for_rmods_after_connection_reset(available_bbmods_list)
        available_rmods = self.rmods_frame.get_configuration()
        available_rmods_list = [
            f'{next(iter(available_rmods[i]))} (RMOD-{i})'
            for i in sorted(available_rmods.keys())
        ]
        self.cells_frame.update_available_rmods(available_rmods_list)
        self.cells_frame.update_selected_antennas()
        # self.event_generate('<<RequireValidation>>')

    def get_configuration(self):
        return {
            'bbmods': self.bbmods_frame.get_configuration(),
            'smods': self.smods_frame.get_configuration(),
            'rmods': self.rmods_frame.get_configuration(),
            'cells': self.cells_frame.get_configuration()
        }

    def prior_delete_bbmod(self, event):
        bbmod_combobox = event.widget.children['additonal_bbmod_frame'].children['bbmod_combobox']
        self.bbmod_name_to_be_deleted = f'{bbmod_combobox.get()} ({bbmod_combobox.master.master["text"]})'
        bbmods_dictionary = self.bbmods_frame.get_bbmods()
        self.available_bbmods_list_prior_bbmod_deletion = [
            f'{bbmod.get_choosen_bbmod()} (BBMOD-{idx})'
            for idx, bbmod in sorted(bbmods_dictionary.items(), key=lambda item: item[0])
            if bbmod.get_choosen_bbmod()
        ]

    def post_delete_bbmod(self, event):
        bbmods_dictionary = self.bbmods_frame.get_bbmods()
        available_bbmods_list = [
            f'{bbmod.get_choosen_bbmod()} (BBMOD-{idx})'
            for idx, bbmod in sorted(bbmods_dictionary.items(), key=lambda item: item[0])
            if bbmod.get_choosen_bbmod()
        ]
        idx = int(re.search(r'(\d+)', self.bbmod_name_to_be_deleted).group(1))
        self.rmods_frame.reset_connection_after_bbmod_deletion(self.bbmod_name_to_be_deleted, available_bbmods_list,
                                                               self.available_bbmods_list_prior_bbmod_deletion, idx)
        self.post_cell_update()
        self.bbmod_name_to_be_deleted = None
        self.event_generate('<<RequireValidation>>')

    def prior_reset_rmod(self, event):
        pass

    def post_reset_rmod(self, event=None):
        available_bbmods_list = self.fetch_bbmods_func()
        self.rmods_frame.update_available_bbmods_for_rmods_after_connection_reset(available_bbmods_list)
        available_rmods = self.rmods_frame.get_configuration()
        available_rmods_list = [
            f'{next(iter(available_rmods[i]))} (RMOD-{i})'
            for i in sorted(available_rmods.keys())
        ]
        self.cells_frame.update_available_rmods(available_rmods_list)
        self.event_generate('<<RequireValidation>>')

    def prior_delete_rmod(self, event):
        self.rmod_id_to_be_deleted = re.search(r'(\d+)', event.widget['text']).group(1)  # for updating cell frame

    def post_delete_rmod(self, event):
        available_bbmods_list = self.fetch_bbmods_func()
        self.rmods_frame.update_available_bbmods_for_rmods_after_connection_reset(available_bbmods_list)
        self.post_cell_update()
        self.rmod_id_to_be_deleted = None
        self.event_generate('<<RequireValidation>>')

    def post_cell_update(self, event=None):
        available_rmods = self.rmods_frame.get_configuration()
        available_rmods_list = [f'{next(iter(available_rmods[i]))} (RMOD-{i})' for i in sorted(available_rmods.keys())]
        self.cells_frame.update_available_rmods(available_rmods_list, self.rmod_id_to_be_deleted)
        self.event_generate('<<RequireValidation>>')

    # flake8: noqa: C901
    def update_configuration(self, event):
        widget_name = str(event.widget).split(".")[-1]
        logger.info(f"{event.widget} selected with value {event.widget.get()}")
        if widget_name == 'bbmod_type':  # rmods_frame
            available_bbmods_list = self.fetch_bbmods_func()
            self.rmods_frame.update_links_for_selected_bbmod(event, available_bbmods_list)
            available_rmods = self.rmods_frame.get_configuration()
            available_rmods_list = [f'{next(iter(available_rmods[i]))} (RMOD-{i})' for i in
                                    sorted(available_rmods.keys())]
            self.cells_frame.update_available_rmods(available_rmods_list)
        elif widget_name == 'port_combobox':
            available_bbmods_list = self.fetch_bbmods_func()
            self.rmods_frame.update_available_links_bbmod(event, available_bbmods_list)
            self.rmods_frame.update_available_bbmods_for_rmods_after_connection_reset(available_bbmods_list)
            available_rmods = self.rmods_frame.get_configuration()
            available_rmods_list = [f'{next(iter(available_rmods[i]))} (RMOD-{i})' for i in sorted(available_rmods.keys())]
            self.cells_frame.update_available_rmods(available_rmods_list)
        elif widget_name == 'bbmod_combobox':
            available_bbmods_list = self.fetch_bbmods_func()
            self.rmods_frame.update_available_bbmods_for_rmods(available_bbmods_list)
            self.post_cell_update()
        elif widget_name == 'rmod_type_combobox':
            rmod_idx = re.search(r'(\d+)', event.widget.master.master.master['text']).group(1)
            available_rmods = self.rmods_frame.get_configuration()
            available_rmods_list = [f'{next(iter(available_rmods[i]))} (RMOD-{i})' for i in sorted(available_rmods.keys())]
            self.cells_frame.update_available_rmods_and_reset_changed_rmod(available_rmods_list, rmod_idx)
        elif widget_name == 'rmod':
            self.cells_frame.update_antennas_after_rmod_selection(event)
            available_rmods = self.rmods_frame.get_configuration()
            available_rmods_list = [f'{next(iter(available_rmods[i]))} (RMOD-{i})' for i in sorted(available_rmods.keys())]
            self.cells_frame.update_available_rmods(available_rmods_list)
        elif widget_name == 'smod_combobox':
            smod_type = event.widget.get()
            if smod_type in ('ASOF', 'ASOE',):
                self.rmods_frame.reset()
                self.cells_frame.reset()
                self.bbmods_frame.full_reset()
                self.fetch_bbmods_func = self.fetch_smods
                self.update_view_config()  # get rid of set values in comboboxes
                self.event_generate('<<NewTypeSmodSelected>>')  # propagate event to lock bbmod section

            elif self.fetch_bbmods_func == self.fetch_smods:
                self.fetch_bbmods_func = self.fetch_bbmods
                self.rmods_frame.reset(event=False)
                self.cells_frame.reset()
                self.bbmods_frame.full_reset()
                self.update_view_config()
                self.event_generate('<<UnlockBbmodSelected>>')

        if 'viewacg' in str(event.widget):
            self.event_generate('<<RequireValidation>>')

    def fetch_bbmods(self):
        bbmods_dictionary = self.bbmods_frame.get_bbmods()
        available_bbmods_list = [
            f'{bbmod.get_choosen_bbmod()} (BBMOD-{idx})'
            for idx, bbmod in sorted(bbmods_dictionary.items(), key=lambda item: item[0])
            if bbmod.get_choosen_bbmod()
        ]

        return available_bbmods_list

    def fetch_smods(self):
        smods_dictionary = self.smods_frame.get_smods()
        available_bbmods_list = [
            f'{smod.get_smod_config()} (SMOD-{idx})'
            for idx, smod in sorted(smods_dictionary.items(), key=lambda item: item[0])
            if smod.get_smod_config()
        ]

        return available_bbmods_list

    def get_validation_log(self, selected_profile):
        if self.fetch_bbmods_func == self.fetch_bbmods:
            return [
                self.bbmods_frame.get_validation_log(),
                self.smods_frame.get_validation_log(),
                self.rmods_frame.get_validation_log(),
                self.cells_frame.get_validation_log(selected_profile)
            ]

        return [
            self.smods_frame.get_validation_log(),
            self.rmods_frame.get_validation_log(),
            self.cells_frame.get_validation_log(selected_profile)
        ]
